1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * When the create request sets {@code sharesHousehold} true and the new owner joins a household
10	 * already occupied by an existing owner (same last name and address, see {@link HouseholdNormalizer}),
11	 * stamps the new owner and every existing member of that household with the same stable
12	 * {@link HouseholdNormalizer#id(String, String) household id}. Without {@code sharesHousehold} the
13	 * new owner is never treated as a joiner, so a lone owner keeps a null household id. The assigned id
14	 * becomes the household part of the {@link IdentityKey duplicate key} that {@link EnsureUniqueIdentity}
15	 * checks next, so two members of one household are distinguished only by their other key parts. Runs
16	 * after {@link BuildOwner} and mutates the built {@link Owner} in place; existing members are re-saved
17	 * so a later read returns the shared id too.
18	 */
19	public class AssignHousehold {
20	
21	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
22	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return;
24	        }
25	        String key = HouseholdNormalizer.key(owner.getLastName(), owner.getAddress());
26	        boolean joinsHousehold = false;
27	        String householdId = HouseholdNormalizer.id(owner.getLastName(), owner.getAddress());
28	        for (Owner member : ownerRepository.findAll()) {
29	            if (!key.equals(HouseholdNormalizer.key(member.getLastName(), member.getAddress()))) {
30	                continue;
31	            }
32	            joinsHousehold = true;
33	            if (!householdId.equals(member.getHouseholdId())) {
34	                member.setHouseholdId(householdId);
35	                ownerRepository.save(member);
36	            }
37	        }
38	        if (joinsHousehold) {
39	            owner.setHouseholdId(householdId);
40	        }
41	    }
42	}
43

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.util.Sha256;
4	
5	/**
6	 * Canonical household comparison shared by the create pipeline: {@link AssignHousehold} uses it to
7	 * decide whether two owners share a household and to derive the shared household id (which in turn
8	 * feeds the household part of the {@link IdentityKey duplicate key}). A household is identified by last
9	 * name plus address: the last name is compared
10	 * case-insensitively with runs of whitespace collapsed to a single space and outer whitespace trimmed,
11	 * and the address is compared in its canonical form (see {@link AddressNormalizer}). Not a pipeline
12	 * step, so it is free to expose plain helpers.
13	 */
14	public final class HouseholdNormalizer {
15	
16	    private HouseholdNormalizer() {
17	    }
18	
19	    /**
20	     * The stable household identifier derived from an owner's last name and address. Owners with
21	     * equal {@link #key(String, String) keys} share the same id, and the id never changes for a given
22	     * household, so it can be recomputed for late joiners rather than stored and looked up.
23	     */
24	    public static String id(String lastName, String address) {
25	        return "H-" + Sha256.prefix(key(lastName, address), 12);
26	    }
27	
28	    /**
29	     * Builds the canonical household key for an owner from its last name and address. Two owners
30	     * belong to the same household when their keys are equal. Either field may be {@code null}, which
31	     * normalizes to an empty token.
32	     */
33	    public static String key(String lastName, String address) {
34	        // '\n' separates the fields so that a boundary shift (e.g. "ab"+"c" vs "a"+"bc") cannot forge a
35	        // collision; it never appears in a normalized value.
36	        return normalizeName(lastName) + "\n" + AddressNormalizer.normalize(address);
37	    }
38	
39	    /** Lower-cases and collapses whitespace to single spaces, trimming the ends; {@code null} → "". */
40	    private static String normalizeName(String value) {
41	        if (value == null) {
42	            return "";
43	        }
44	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
45	    }
46	}
