1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Flags a soft duplicate: a new owner that passed the hard-duplicate check (see
9	 * {@link EnsureUniqueIdentity}) but still shares an existing owner's last name (compared
10	 * case-insensitively) and postcode while giving a different telephone. Such a request is allowed but
11	 * marked for follow-up: the built {@link Owner} records {@code possibleDuplicate} true and
12	 * {@code possibleDuplicateOf} the matching owner's id (the earliest match when several exist).
13	 * When no such owner exists {@code possibleDuplicate} is false and {@code possibleDuplicateOf} stays
14	 * absent. Runs before {@link SaveOwner}, so the new owner is not yet persisted and is never matched
15	 * against itself. Mutates the built {@link Owner} in place.
16	 */
17	public class FlagPossibleDuplicate {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        owner.setPossibleDuplicate(false);
21	        String postcode = trimmed(owner.getPostcode());
22	        if (postcode == null) {
23	            return;
24	        }
25	        Owner match = null;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (owner.getLastName().equalsIgnoreCase(existing.getLastName())
28	                    && postcode.equals(trimmed(existing.getPostcode()))
29	                    && !owner.getTelephone().equals(existing.getTelephone())) {
30	                if (match == null || existing.getId() < match.getId()) {
31	                    match = existing;
32	                }
33	            }
34	        }
35	        if (match != null) {
36	            owner.setPossibleDuplicate(true);
37	            owner.setPossibleDuplicateOf(match.getId());
38	        }
39	    }
40	
41	    private static String trimmed(String value) {
42	        if (value == null) {
43	            return null;
44	        }
45	        String result = value.trim();
46	        return result.isEmpty() ? null : result;
47	    }
48	}
